package com.insight.quantlife.tests;
import android.app.*;import android.os.Bundle;import org.json.*;import java.io.*;import com.insight.quantlife.*;
public class LinkUpgradeTest extends Instrumentation {
 int passed;void check(boolean b,String s)throws Exception{if(!b)throw new Exception(s);passed++;Bundle o=new Bundle();o.putString("stream","PASS "+s+"\n");sendStatus(0,o);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle out=new Bundle();try{ByteArrayOutputStream buffer=new ByteArrayOutputStream();try(InputStream f=getTargetContext().openFileInput("link-upgrade-snapshot.json")){byte[] b=new byte[4096];int n;while((n=f.read(b))!=-1)buffer.write(b,0,n);}JSONObject snap=new JSONObject(buffer.toString("UTF-8"));MainHost h=new MainHost(this);h.open();JSONObject now=(JSONObject)h.call("init",new JSONObject());for(String field:new String[]{"records","messages","wikiPages","settings"})check(now.get(field).toString().equals(snap.get(field).toString()),"1.3.3 to1.4.0 upgrade preserves "+field);try(TrackStore db=new TrackStore(getTargetContext())){check(db.gpx("2026-10-17").equals(snap.getString("gpx")),"GPX unchanged by link feature");check(db.diagnostics("2026-10-17").getJSONArray("rawPoints").toString().equals(snap.getJSONArray("raw").toString()),"GPS raw data unchanged");}check(!now.has("points"),"AI initialization excludes GPS");out.putString("stream","PASS: "+passed+" upgrade checks\n");finish(Activity.RESULT_OK,out);}catch(Throwable e){out.putString("stream","FAIL after "+passed+": "+e);finish(Activity.RESULT_CANCELED,out);}}
}
